"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1327],{41270:e=>{e.exports=JSON.parse('{"functions":[{"name":"getSize","desc":"Usable screen size in pixels.\\n\\nMeasured off a private `DeviceScreen` ScreenGui with insets and safe-area\\ncompatibility disabled, so this is the raw viewport rather than whatever\\na particular ScreenGui\'s inset settings would report.","params":[],"returns":[{"desc":"","lua_type":"Vector2"}],"function_type":"static","source":{"line":136,"path":"src/Client/Util/Device.luau"}},{"name":"getWidth","desc":"Usable screen width in pixels. Width is what breakpoints are keyed on.","params":[],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":148,"path":"src/Client/Util/Device.luau"}},{"name":"hasTouchControls","desc":"Whether on-screen touch controls are in play \u2014 touch is enabled and this\\nis not a console. Distinct from [Device.isMobile]: a laptop with a\\ntouchscreen answers true here and false there.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":162,"path":"src/Client/Util/Device.luau"}},{"name":"getBreakpoint","desc":"The breakpoint matching the current screen width.\\n\\nWalks the thresholds largest-first and returns the first one the width\\nexceeds, so a width below every threshold lands on the smallest. Note\\nthat several breakpoint names share a pixel value (`phone-small` and\\n`phone` are both 640, and everything from `laptop-medium` up is 1536), so\\nthe name returned for a shared value is whichever the flipped lookup\\ntable happens to hold \u2014 compare with [Device.inBreakpoint] rather than\\ntesting this for equality.","params":[],"returns":[{"desc":"","lua_type":"Breakpoint"}],"function_type":"static","source":{"line":182,"path":"src/Client/Util/Device.luau"}},{"name":"inBreakpoint","desc":"Whether the current breakpoint is at or below `target` \u2014 the\\n\\"max-width\\" test, so `inBreakpoint(\\"phone-large\\")` is true on every phone\\nand false on tablets and up.\\n\\nThis is the intended way to branch on screen size; it compares pixel\\nthresholds rather than breakpoint names, so aliased names behave\\nsensibly. Reads the cached `lastBreakpoint` rather than re-measuring.","params":[{"name":"target","desc":"Upper bound to test against","lua_type":"Breakpoint"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":212,"path":"src/Client/Util/Device.luau"}},{"name":"isConsole","desc":"Whether the client is running on a console (ten-foot interface).","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":226,"path":"src/Client/Util/Device.luau"}},{"name":"forcedInputDevice","desc":"In Studio only, the input device a `ForceInputDevice` attribute on\\nWorkspace names (\\"gamepad\\", \\"keyboard\\" or \\"touch\\"), so a Play session can\\nwalk the gamepad paths that Studio\'s automation can\'t drive: it sends\\ngamepad key codes as keyboard input. nil everywhere else.","params":[],"returns":[{"desc":"","lua_type":"string?"}],"function_type":"static","source":{"line":241,"path":"src/Client/Util/Device.luau"}},{"name":"isMobile","desc":"Whether this device should get the mobile UI: any touch-capable,\\nnon-console device. See the inline comment for why this is not the\\nstricter \\"touch and no keyboard/mouse\\" check.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":288,"path":"src/Client/Util/Device.luau"}}],"properties":[],"types":[],"name":"Device","desc":"Author: Javi (dig1t)\\n\\nUtility module for handling device-specific information and events.\\n\\nBreakpoints are thresholds that trigger responsive elements to resize/reshape.\\nThey are used for adjust UI to different screen sizes and devices.","realm":["Client"],"source":{"line":15,"path":"src/Client/Util/Device.luau"}}')}}]);